class MessageQueue:
    def __init__(self, cap: int) -> None:
        self._cap = cap
        self._q: deque = deque()
        self._cond = threading.Condition()     # lock + condition in one object

    def put(self, item) -> None:
        with self._cond:
            self._cond.wait_for(lambda: len(self._q) < self._cap)
            self._q.append(item)
            self._cond.notify_all()

